{
  "policy_type": "rules",
  "name": "policy_ep_40",
  "rules": [
    {
      "if": [
        { "feature": "vy", "op": "<", "value": -0.5 },
        { "feature": "theta", "op": ">", "value": -0.1 },
        { "feature": "theta", "op": "<", "value": 0.1 }
      ],
      "then": 2
    },
    {
      "if": [
        { "feature": "x", "op": "<", "value": 0.5 },
        { "feature": "x", "op": ">", "value": -0.5 },
        { "feature": "vx", "op": ">", "value": 0.1 }
      ],
      "then": 3
    },
    {
      "if": [
        { "feature": "left_leg", "op": "==", "value": 1 },
        { "feature": "right_leg", "op": "==", "value": 1 }
      ],
      "then": 0
    },
    {
      "if": [
        { "feature": "vy", "op": ">", "value": -0.5 },
        { "feature": "theta", "op": "<", "value": -0.1 },
        { "feature": "theta", "op": ">", "value": 0.1 }
      ],
      "then": 1
    }
  ],
  "default_action": 0,
  "notes": "This new policy is influenced by the need to improve landing stability and reduce crashes. It modifies the rule that fires the main engine when vertical velocity is too high, as seen in previous successful trajectories, while maintaining the successful rule for firing the orientation engine when horizontal velocity is too high. The previous policy had an evaluated return of 50 with 60% coverage in the stable landing region, which indicated the need for adjustments in vertical control during descent."
}

